// Isolated public HTTP shapes from the one canonical map. No live service/identity.
import {readFile} from 'node:fs/promises';
import {createHash} from 'node:crypto';
export const layoutSha='93a2a1e8b30d2f04d85a3974326295f68360b3dd80b219dcbee111d78d3b7732',geometryDigest='b2c52a8a77dcf352670d5fb95a755d442c5a424c27d4762b921e0ce817d4f772';
export const epoch=Date.parse('2026-10-23T12:00:00+08:00'),appearance={lookId:'sunnyside-human-longhair',catalogVersion:'2026-10-21.appearance-v1.1'};
export async function townFixture(){
 const bytes=await readFile(process.env.TOWN_V2_LAYOUT_PATH||new URL('../../apps/web/public/world-map-v2.json',import.meta.url));if(createHash('sha256').update(bytes).digest('hex')!==layoutSha)throw Error('fixture_layout_mismatch');const layout=JSON.parse(bytes.toString()),point=(cell:number[])=>({x:cell[0]!,y:cell[1]!});
 const npcs=layout.npcServicePoints.map((n:any)=>({npcId:n.id,name:n.name,role:n.role,position:point(n.standingCell),approachCells:n.approachCells.map(point),appearance:{...appearance,lookId:'sunnyside-human-'+n.hair},serverManaged:true,readOnly:true,actions:[],status:'service_unavailable',countsAsAgent:false}));
 const manifest={mapId:'pixel-town-v2',version:2,layoutUrl:'/world-map-v2.json',layoutSha256:layoutSha,geometryDigest,source:{width:1536,height:1152},tileSize:16,origin:{x:520,y:520},bounds:layout.bounds,counts:{walkable:1150,physicalBlocked:1622,unopened:2860},singleSurface:true,visualElevationOnly:true,buildings:layout.buildings.map((b:any)=>({id:b.id,name:b.name,entrance:point(b.entrance.cell),interior:false})),bridges:layout.bridges.map((b:any)=>({id:b.id,name:b.name,deckCells:b.deckCells.map(point),bankApproachCells:b.bankApproachCells.map(point)})),stairs:layout.stairs.map((s:any)=>({id:s.id,name:s.name,cells:s.cells.map(point),lowerEndpoint:point(s.lowerEndpoint),upperEndpoint:point(s.upperEndpoint)})),npcs};
 const rules={worldId:'default',version:2,topologyVersion:2,width:88,height:64,bounds:layout.bounds,mapManifest:manifest,places:[{id:'commons',access:'members'}]};return{bytes,layout,manifest,rules,npcs};
}
export function avatar(agentId:string,position={x:0,y:0},version=1,motion:any=null){return{id:'avatar-'+agentId,worldId:'default',agentId,version,status:'idle',position,motion,placeId:position.x>=0&&position.x<16&&position.y>=0&&position.y<16?'commons':null,rulesetVersion:2,createdAt:1,updatedAt:epoch,profile:{agentId,publishedVersion:1,displayName:'工程角色 '+agentId,appearance}};}
export function edge(agentId:string,version:number,from:{x:number;y:number},to:{x:number;y:number},startedAt=epoch,source='explicit'){return{segmentId:'avatar-'+agentId+':'+version,movementId:source==='idle'?null:'synthetic-plan',source,from,to,startedAt,arriveAt:startedAt+(source==='idle'?4000:1000),rulesetVersion:2,topologyVersion:2,status:'committed'};}
